insert into public.problems (id, title, statement, input_spec, output_spec, notes, examples, tags, rating, time_limit_ms, visibility) values (1021, 'Fewest Coins', 'You have coins of several values (unlimited of each). What is the smallest number of coins that adds up to exactly S? If it is impossible print -1.', 'The first line contains k and S (1 ≤ k ≤ 50, 0 ≤ S ≤ 10^4). The second line contains k coin values (1 ≤ c_i ≤ 10^4).', 'Print the minimum number of coins, or -1.', 'Greedy (always take the biggest coin) is wrong: with coins 1, 3, 4 and S = 6 the answer is 3 + 3 (2 coins), not 4 + 1 + 1.', '[{"input":"3 6\n1 3 4\n","output":"2"},{"input":"1 3\n2\n","output":"-1"}]'::jsonb, array['dp']::text[], 1500, 2000, 'public') on conflict (id) do nothing;
